def parse_query(qs: str) -> dict:
    def _decode(s: str) -> str:
        # Replace '+' with space
        s = s.replace('+', ' ')
        out = bytearray()
        i = 0
        hexdigits = '0123456789abcdefABCDEF'
        while i < len(s):
            c = s[i]
            if c == '%':
                if i + 2 >= len(s):
                    raise ValueError("malformed percent-escape")
                h = s[i+1:i+3]
                if not all(ch in hexdigits for ch in h):
                    raise ValueError("malformed percent-escape")
                out.append(int(h, 16))
                i += 3
            else:
                out.extend(c.encode('utf-8'))
                i += 1
        try:
            return out.decode('utf-8')
        except UnicodeDecodeError as exc:
            raise ValueError("malformed percent-escape or invalid UTF-8") from exc

    result = {}
    for pair in qs.split('&'):
        if pair == '':
            continue
        if '=' in pair:
            key, val = pair.split('=', 1)
        else:
            key, val = pair, ''
        key = _decode(key)
        val = _decode(val)
        result.setdefault(key, []).append(val)
    return result
